-- 20260808120500_storage.sql
-- ======================================================================

-- Charta Home · private storage buckets
-- Paths always begin with the agency id so a policy can check membership:
--   building-photos/<agency_id>/<building_id>/<file>

insert into storage.buckets (id, name, public)
values
  ('building-photos', 'building-photos', false),
  ('apartment-photos', 'apartment-photos', false),
  ('receipts', 'receipts', false),
  ('documents', 'documents', false)
on conflict (id) do nothing;

-- Objects are readable and writable only by members of the agency named in the
-- first path segment.
create policy "charta members read objects"
on storage.objects for select
to authenticated
using (
  bucket_id in ('building-photos', 'apartment-photos', 'receipts', 'documents')
  and public.is_member(((storage.foldername(name))[1])::uuid)
);

create policy "charta members upload objects"
on storage.objects for insert
to authenticated
with check (
  bucket_id in ('building-photos', 'apartment-photos', 'receipts', 'documents')
  and public.is_member(((storage.foldername(name))[1])::uuid)
);

create policy "charta members update objects"
on storage.objects for update
to authenticated
using (
  bucket_id in ('building-photos', 'apartment-photos', 'receipts', 'documents')
  and public.is_member(((storage.foldername(name))[1])::uuid)
);

create policy "charta members delete objects"
on storage.objects for delete
to authenticated
using (
  bucket_id in ('building-photos', 'apartment-photos', 'receipts', 'documents')
  and public.is_member(((storage.foldername(name))[1])::uuid)
);

-- ======================================================================
-- 20260808120600_photos_and_technicians.sql
-- ======================================================================

-- Charta Home · apartment photo galleries and technician performance

-- ------------------------------------------------------- apartment photos
-- An apartment has an ordered gallery rather than a single photo column, so
-- images can be added, reordered and removed independently.

create table apartment_photos (
  id           uuid primary key default gen_random_uuid(),
  agency_id    uuid not null references agencies (id) on delete cascade,
  apartment_id uuid not null references apartments (id) on delete cascade,
  storage_path text not null,
  caption      text,
  position     smallint not null default 0,
  created_at   timestamptz not null default now()
);

create index apartment_photos_apartment_idx on apartment_photos (apartment_id, position);
create index apartment_photos_agency_idx on apartment_photos (agency_id);

alter table apartment_photos enable row level security;

create policy apartment_photos_select on apartment_photos for select
  using (agency_id in (select public.current_agency_ids()));

create policy apartment_photos_write on apartment_photos for all
  using (public.has_role(agency_id, array['owner', 'manager', 'accountant']::public.member_role[]))
  with check (public.has_role(agency_id, array['owner', 'manager', 'accountant']::public.member_role[]));

-- Keep positions contiguous when a photo is removed.
create or replace function public.reorder_apartment_photos()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.apartment_photos p
  set position = ordered.new_position
  from (
    select id, (row_number() over (order by position, created_at) - 1)::smallint as new_position
    from public.apartment_photos
    where apartment_id = old.apartment_id
  ) ordered
  where p.id = ordered.id and p.position is distinct from ordered.new_position;

  return null;
end;
$$;

create trigger apartment_photos_reorder after delete on apartment_photos
  for each row execute function public.reorder_apartment_photos();

-- --------------------------------------------------- technician performance
-- Powers the technicians tab: how many jobs, how much paid, how fast.

create view v_technician_performance
with (security_invoker = true)
as
select
  tech.id                as technician_id,
  tech.agency_id,
  tech.full_name,
  tech.trade,
  tech.phone_e164,
  tech.is_external,
  count(t.id)                                              as jobs_total,
  count(t.id) filter (where t.status = 'resolved')          as jobs_resolved,
  count(t.id) filter (where t.status <> 'resolved')         as jobs_open,
  coalesce(sum(t.cost) filter (where t.status = 'resolved'), 0)::bigint as total_paid,
  round(
    avg(
      extract(epoch from (t.resolved_at - t.opened_at)) / 86400
    ) filter (where t.status = 'resolved')::numeric,
    1
  )                       as avg_days_to_resolve,
  max(t.resolved_at)      as last_job_at
from technicians tech
left join tickets t on t.technician_id = tech.id
group by tech.id;

-- ------------------------------------------------------------ reassignment
-- Reassigning is not a plain update: it should record who took over and reset
-- the ticket to assigned so the new technician sees it as fresh work.

create or replace function public.assign_technician(
  target_ticket uuid,
  target_technician uuid,
  estimated_cost bigint default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  tk record;
  tech record;
begin
  select * into tk from public.tickets where id = target_ticket;
  if not found then
    raise exception 'ticket % not found', target_ticket;
  end if;
  if not public.is_member(tk.agency_id) then
    raise exception 'not a member of this agency';
  end if;

  select * into tech from public.technicians where id = target_technician;
  if not found or tech.agency_id <> tk.agency_id then
    raise exception 'technician % is not in this agency', target_technician;
  end if;

  update public.tickets
  set technician_id = target_technician,
      status = case when status = 'resolved' then status else 'assigned' end,
      cost = coalesce(estimated_cost, cost)
  where id = target_ticket;

  insert into public.ticket_messages (agency_id, ticket_id, direction, body)
  values (
    tk.agency_id,
    target_ticket,
    'outbound',
    case
      when tk.technician_id is null then 'Assigné à ' || tech.full_name
      else 'Réassigné à ' || tech.full_name
    end
  );
end;
$$;

grant execute on function public.assign_technician to authenticated;

-- ======================================================================
-- 20260808120700_settings.sql
-- ======================================================================

-- Charta Home · settings page support
--
-- The settings screen needs the team roster with each member's email, and
-- auth.users is not reachable through PostgREST. list_agency_members bridges
-- it the same way the rest of the schema bridges auth: a security definer
-- function that checks membership itself rather than trusting the caller.

create or replace function public.list_agency_members(target_agency uuid)
returns table (
  user_id    uuid,
  full_name  text,
  role       public.member_role,
  email      text,
  created_at timestamptz
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not public.is_member(target_agency) then
    raise exception 'not a member of this agency';
  end if;

  return query
    select m.user_id, m.full_name, m.role, u.email::text, m.created_at
    from public.memberships m
    join auth.users u on u.id = m.user_id
    where m.agency_id = target_agency
    order by m.created_at;
end;
$$;

grant execute on function public.list_agency_members to authenticated;

comment on function public.list_agency_members is
  'The settings team roster, email included. Raises unless the caller belongs to the agency.';

-- ======================================================================
-- 20260808120800_lease_end_date.sql
-- ======================================================================

-- Charta Home · lease end date
--
-- `leases.ends_on` has existed since the portfolio migration, with a check
-- that it cannot precede the start, but nothing could set it: create_lease
-- took no such argument and v_apartment_state never selected it. An agency
-- signing a fixed term lease had nowhere to record when the tenant leaves.

-- The view gains the column. Replaced rather than dropped, because
-- v_building_performance is built on top of it and a drop would take that
-- with it. create or replace can only append, so lease_ends_on goes last
-- even though it reads better beside lease_started_on.
create or replace view v_apartment_state
with (security_invoker = true)
as
select
  ap.id            as apartment_id,
  ap.agency_id,
  ap.building_id,
  ap.label,
  ap.rooms,
  ap.bathrooms,
  ap.sqm,
  ap.base_rent,
  l.id             as lease_id,
  l.cycle,
  l.rent_amount,
  r.id             as resident_id,
  r.full_name      as resident_name,
  r.phone_e164     as resident_phone,
  l.starts_on      as lease_started_on,
  (l.id is not null) as is_occupied,
  case
    when l.id is null then null
    else (
      select cs.state
      from v_charge_status cs
      where cs.lease_id = l.id
      order by cs.period_start desc
      limit 1
    )
  end as rent_state,
  l.ends_on        as lease_ends_on
from apartments ap
left join leases l
  on l.apartment_id = ap.id and l.status = 'active'
left join residents r
  on r.id = l.resident_id;

-- Dropped rather than replaced: adding a defaulted parameter would leave the
-- old signature in place and make every existing call ambiguous.
drop function if exists public.create_lease(uuid, text, text, bigint, lease_cycle, date, bigint);

create function public.create_lease(
  target_apartment uuid,
  resident_name text,
  resident_phone text,
  rent bigint,
  cycle_in lease_cycle default 'monthly',
  starts_on_in date default current_date,
  deposit_in bigint default 0,
  ends_on_in date default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  ap record;
  resident uuid;
  new_lease uuid;
begin
  select * into ap from public.apartments where id = target_apartment;
  if not found then
    raise exception 'apartment % not found', target_apartment;
  end if;
  if not public.has_role(ap.agency_id, array['owner', 'manager']::public.member_role[]) then
    raise exception 'not allowed to create leases for this agency';
  end if;

  -- A move out date before the move in date is a typo, not a lease.
  if ends_on_in is not null and ends_on_in < starts_on_in then
    raise exception 'lease cannot end before it starts';
  end if;

  select id into resident
  from public.residents
  where agency_id = ap.agency_id and phone_e164 = resident_phone
  limit 1;

  if resident is null then
    insert into public.residents (agency_id, full_name, phone_e164)
    values (ap.agency_id, resident_name, resident_phone)
    returning id into resident;
  end if;

  insert into public.leases (
    agency_id, apartment_id, resident_id, cycle, rent_amount, deposit,
    starts_on, ends_on, status
  )
  values (
    ap.agency_id, ap.id, resident, cycle_in, rent, deposit_in,
    starts_on_in, ends_on_in, 'active'
  )
  returning id into new_lease;

  perform public.ensure_rent_charge(new_lease, starts_on_in);

  return new_lease;
end;
$$;

grant execute on function public.create_lease to authenticated;

-- ======================================================================
-- 20260808120900_reminder_messages.sql
-- ======================================================================

-- Charta Home · editable reminder messages
--
-- Until now a reminder rule knew when to fire and on what channel, but not
-- what to say. The agency needs to write that themselves: the tone an agency
-- in Conakry uses with its tenants is theirs, not ours.
--
-- message_body holds the text with placeholders the dispatcher fills in:
--   {tenant} {amount} {period} {days} {agency} {apartment}
--
-- template_name stays alongside it. Meta refuses free text outside the 24 hour
-- customer service window, so a proactive reminder needs an approved template;
-- the body is then what the agency submitted for approval and what fills the
-- template's variables.

alter table reminder_rules
  add column if not exists message_body text;

-- Sensible French defaults so an agency is never left with a blank message.
-- Matched on the sign of the offset rather than an exact value, since the
-- courtesy lead time is the agency's to choose.
update reminder_rules
set message_body = case
  when offset_days < 0 then
    'Bonjour {tenant}, votre loyer de {amount} pour {apartment} est attendu dans {days} jours, le {period}. Merci de votre confiance. {agency}'
  when offset_days = 0 then
    'Bonjour {tenant}, votre loyer de {amount} pour {apartment} est dû aujourd''hui. Merci de votre confiance. {agency}'
  when escalation_step >= 2 then
    'Bonjour {tenant}, le loyer de {amount} pour {apartment} reste impayé depuis {days} jours. Merci de nous contacter rapidement. {agency}'
  else
    'Bonjour {tenant}, nous n''avons pas encore reçu le loyer de {amount} pour {apartment}, dû le {period}. Merci de régulariser. {agency}'
end
where message_body is null;

comment on column reminder_rules.message_body is
  'What the reminder says. Placeholders: {tenant} {amount} {period} {days} {agency} {apartment}.';

-- The dispatcher needs the resident's name and number, the unit, and the
-- agency's WhatsApp identity, all of which sit several joins from a charge.
-- One view so the cron reads a queue rather than assembling it row by row.
create or replace view v_reminder_targets
with (security_invoker = true)
as
select
  rc.id            as rent_charge_id,
  rc.agency_id,
  rc.due_on,
  rc.amount,
  ag.name          as agency_name,
  ag.whatsapp_number as agency_whatsapp,
  ag.currency,
  r.full_name      as resident_name,
  r.phone_e164     as resident_phone,
  ap.label         as apartment_label
from rent_charges rc
join leases l    on l.id = rc.lease_id
join residents r on r.id = l.resident_id
join apartments ap on ap.id = l.apartment_id
join agencies ag on ag.id = rc.agency_id;

-- ======================================================================
-- 20260808121000_integrity_and_limits.sql
-- ======================================================================

-- Charta Home · guards that belong in the database
--
-- Two of these existed only in application code, which means they held for the
-- dashboard and not for anyone calling PostgREST directly with their own token.
-- A rule that protects payment history should not depend on which client asked.

-- ------------------------------------------- deleting an occupied apartment
-- apartments cascades to leases, which cascades to rent_charges and payments.
-- Deleting a unit somebody still lives in therefore erases the money it has
-- collected. The server action refused this already; now the database does.

create or replace function public.block_delete_occupied_apartment()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if exists (
    select 1 from public.leases
    where apartment_id = old.id and status = 'active'
  ) then
    raise exception 'apartment % still has an active lease', old.id
      using errcode = 'restrict_violation',
            hint = 'End the lease before deleting the unit.';
  end if;
  return old;
end;
$$;

drop trigger if exists apartments_block_occupied_delete on apartments;
create trigger apartments_block_occupied_delete
  before delete on apartments
  for each row execute function public.block_delete_occupied_apartment();

-- ------------------------------------------------------------ rate limiting
-- The WhatsApp webhook verifies Meta's signature but nothing bounded how often
-- it could be called. Serverless instances share no memory, so the counter
-- lives in Postgres, which every instance already talks to.

create table if not exists rate_limits (
  bucket       text primary key,
  window_start timestamptz not null default now(),
  hits         integer not null default 0
);

alter table rate_limits enable row level security;
-- No policies: only the service role, which bypasses RLS, ever touches this.

comment on table rate_limits is
  'Fixed window counters for unauthenticated endpoints. Service role only.';

/**
 * Records one hit and reports whether it is allowed.
 *
 * A fixed window rather than a sliding one: it is one row and one statement,
 * and for shedding a flood the difference does not matter. The upsert makes
 * the read and the increment a single atomic step, so two instances arriving
 * together cannot both see the count below the limit.
 */
create or replace function public.take_rate_limit(
  bucket_key text,
  max_hits integer,
  window_seconds integer
)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  current_hits integer;
begin
  insert into public.rate_limits (bucket, window_start, hits)
  values (bucket_key, now(), 1)
  on conflict (bucket) do update
    set hits = case
          when public.rate_limits.window_start < now() - make_interval(secs => window_seconds)
            then 1
          else public.rate_limits.hits + 1
        end,
        window_start = case
          when public.rate_limits.window_start < now() - make_interval(secs => window_seconds)
            then now()
          else public.rate_limits.window_start
        end
  returning hits into current_hits;

  return current_hits <= max_hits;
end;
$$;

revoke all on function public.take_rate_limit from public;

